names = [n for n in repo.list("data") if n.endswith(".txt")]
counts = {}
total = 0
for n in sorted(names):
    c = repo.read("data/" + n)
    if c == "":
        lines = 0
    else:
        lines = c.count("\n")
        if not c.endswith("\n"):
            lines += 1
    counts[n] = lines
    total += lines
return {"counts": counts, "total": total, "changed": repo.status()}
